      --card-shadow: 0 4px 20px 0 rgba(0, 0, 0, 0.3);
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      background-color: var(--bg-primary);
      color: var(--text-main);
      min-height: 100vh;
      display: flex;
      flex-direction: column;
    }

    header {
      background: linear-gradient(135deg, var(--bg-secondary) 0%, #0f172a 100%);
      border-bottom: 1px solid var(--border-color);
      padding: 24px 40px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 16px;
    }

    .brand-section {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .brand-icon {
      background: linear-gradient(135deg, var(--accent-cyan) 0%, var(--accent-purple) 100%);
      width: 42px;
      height: 42px;
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      box-shadow: 0 0 15px rgba(6, 182, 212, 0.4);
    }

    header h1 {
      font-family: 'Outfit', sans-serif;
      font-size: 26px;
      font-weight: 800;
      letter-spacing: -0.5px;
      background: linear-gradient(to right, #ffffff, #93c5fd);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
    }

    header p {
      font-size: 14px;
      color: var(--text-muted);
      margin-top: 2px;
    }

    .nav-tabs {
      display: flex;
      gap: 8px;
      background-color: var(--bg-primary);
      padding: 6px;
      border-radius: 10px;
      border: 1px solid var(--border-color);
    }

    .tab-btn {
      background: transparent;
      border: none;
      color: var(--text-muted);
      padding: 10px 18px;
      font-size: 14px;
      font-weight: 600;
      border-radius: 8px;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 8px;
      transition: all 0.2s ease;
    }

    .tab-btn:hover {
      color: var(--text-main);
      background-color: rgba(255, 255, 255, 0.05);
    }

    .tab-btn.active {
      color: white;
      background-color: var(--bg-tertiary);
      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
      border: 1px solid var(--border-color);
    }

    main {
      flex: 1;
      max-width: 1280px;
      width: 100%;
      margin: 0 auto;
      padding: 32px 40px;
    }

    .grid-stats {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
      margin-bottom: 32px;
    }

    .stat-card {
      background-color: var(--bg-secondary);
      border: 1px solid var(--border-color);
      border-radius: 16px;
      padding: 24px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      position: relative;
      overflow: hidden;
      box-shadow: var(--card-shadow);
      transition: transform 0.2s ease, border-color 0.2s ease;
    }

    .stat-card:hover {
      transform: translateY(-4px);
      border-color: rgba(255, 255, 255, 0.15);
    }

    .stat-card::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      width: 4px;
      height: 100%;
    }

    .stat-card.workouts::before { background-color: var(--accent-cyan); }
    .stat-card.meals::before { background-color: var(--accent-emerald); }
    .stat-card.vitals::before { background-color: var(--accent-purple); }
    .stat-card.weight::before { background-color: var(--accent-amber); }

    .stat-label {
      font-size: 13px;
      text-transform: uppercase;
      font-weight: 700;
      color: var(--text-muted);
      letter-spacing: 0.5px;
    }

    .stat-value {
      font-family: 'Outfit', sans-serif;
      font-size: 32px;
      font-weight: 800;
      color: white;
      margin-top: 6px;
    }

    .stat-icon {
      background-color: var(--bg-tertiary);
      width: 50px;
      height: 50px;
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      border: 1px solid var(--border-color);
    }

    .stat-card.workouts .stat-icon { color: var(--accent-cyan); }
    .stat-card.meals .stat-icon { color: var(--accent-emerald); }
    .stat-card.vitals .stat-icon { color: var(--accent-purple); }
    .stat-card.weight .stat-icon { color: var(--accent-amber); }

    .dashboard-content {
      display: none;
      animation: fadeIn 0.3s ease-in-out forwards;
    }

    .dashboard-content.active {
      display: block;
    }

    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(10px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .dashboard-grid {
      display: grid;
      grid-template-columns: 1.5fr 1fr;
      gap: 24px;
    }

    .card {
      background-color: var(--bg-secondary);
      border: 1px solid var(--border-color);
      border-radius: 16px;
      padding: 28px;
      box-shadow: var(--card-shadow);
      margin-bottom: 24px;
    }

    .card-title {
      font-family: 'Outfit', sans-serif;
      font-size: 20px;
      font-weight: 700;
      margin-bottom: 20px;
      display: flex;
      align-items: center;
      gap: 10px;
      color: white;
      border-bottom: 1px solid var(--border-color);
      padding-bottom: 12px;
    }

    .card-title i {
      color: var(--accent-cyan);
    }

    .report-box {
      background-color: var(--bg-tertiary);
      border-radius: 12px;
      padding: 24px;
      border: 1px solid var(--border-color);
      font-size: 15px;
      line-height: 1.7;
      white-space: pre-wrap;
      color: #e2e8f0;
      position: relative;
    }

    .report-box::after {
      content: '""';
      position: absolute;
      right: 20px;
      bottom: 10px;
      font-size: 80px;
      color: rgba(255, 255, 255, 0.03);
      font-family: serif;
      line-height: 1;
    }

    .table-container {
      overflow-x: auto;
      border-radius: 12px;
      border: 1px solid var(--border-color);
      background-color: var(--bg-secondary);
    }

    table {
      width: 100%;
      border-collapse: collapse;
      text-align: left;
    }

    th {
      background-color: var(--bg-tertiary);
      color: var(--text-muted);
      font-weight: 600;
      font-size: 13px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      padding: 14px 18px;
      border-bottom: 1px solid var(--border-color);
    }

    td {
      padding: 16px 18px;
      border-bottom: 1px solid var(--border-color);
      color: #cbd5e1;
      font-size: 14px;
      vertical-align: middle;
    }

    tr:last-child td {
      border-bottom: none;
    }

    tr:hover td {
      background-color: rgba(255, 255, 255, 0.02);
    }

    .badge {
      display: inline-flex;
      align-items: center;
      padding: 4px 10px;
      border-radius: 20px;
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
    }

    .badge-breakfast { background-color: rgba(16, 185, 129, 0.15); color: #34d399; }
    .badge-lunch { background-color: rgba(245, 158, 11, 0.15); color: #fbbf24; }
    .badge-dinner { background-color: rgba(6, 182, 212, 0.15); color: #22d3ee; }
    .badge-snack { background-color: rgba(139, 92, 246, 0.15); color: #a78bfa; }
    .badge-default { background-color: rgba(156, 163, 175, 0.15); color: #d1d5db; }

    .condition-text {
      background-color: var(--bg-tertiary);
      border-radius: 6px;
      padding: 4px 8px;
      font-size: 12px;
      border: 1px solid var(--border-color);
      color: var(--text-main);
    }

    .date-col {
      font-weight: 500;
      color: var(--text-muted);
      white-space: nowrap;
    }

    .exercise-badge {
      background-color: rgba(6, 182, 212, 0.1);
      color: var(--accent-cyan);
      border: 1px solid rgba(6, 182, 212, 0.2);
      padding: 4px 10px;
      border-radius: 6px;
      font-weight: 600;
      font-size: 13px;
    }

    .empty-state {
      text-align: center;
      padding: 40px 20px;
      color: var(--text-muted);
      font-size: 14px;
    }

    .empty-state i {
      display: block;
      margin: 0 auto 12px;
      color: var(--border-color);
    }

    @media (max-width: 1024px) {
      .dashboard-grid { grid-template-columns: 1fr; }
      .grid-stats { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 768px) {
      header { padding: 20px; flex-direction: column; align-items: stretch; }
      .nav-tabs { width: 100%; justify-content: space-around; }
      main { padding: 20px; }
      .grid-stats { grid-template-columns: 1fr; }
    }

    .delete-btn {
      background: transparent;
      border: none;
      color: var(--text-muted);
      cursor: pointer;
      padding: 6px;
      border-radius: 6px;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      transition: all 0.2s ease;
    }
    .delete-btn:hover {
      color: #ef4444;
      background-color: rgba(239, 68, 68, 0.1);
    }
    .delete-btn i {
      width: 16px;
      height: 16px;
    }

    /* Modal & Edit Button Styling */
    .modal {
      display: none;
      position: fixed;
      z-index: 1000;
      left: 0;
      top: 0;
      width: 100%;
      height: 100%;
      overflow: auto;
      background-color: rgba(11, 15, 25, 0.8);
      backdrop-filter: blur(4px);
      align-items: center;
      justify-content: center;
    }
    .modal.active {
      display: flex;
    }
    .modal-content {
      background-color: var(--bg-secondary);
      border: 1px solid var(--border-color);
      border-radius: 16px;
      width: 100%;
      max-width: 500px;
      padding: 28px;
      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
      position: relative;
      animation: modalFadeIn 0.2s ease;
    }
    @keyframes modalFadeIn {
      from { transform: scale(0.95); opacity: 0; }
      to { transform: scale(1); opacity: 1; }
    }
    .modal-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 20px;
      border-bottom: 1px solid var(--border-color);
      padding-bottom: 12px;
      color: white;
    }
    .modal-header h3 {
      font-family: 'Outfit', sans-serif;
      font-size: 18px;
      font-weight: 700;
    }
    .close-modal-btn {
      background: transparent;
      border: none;
      color: var(--text-muted);
      cursor: pointer;
      font-size: 20px;
      transition: color 0.2s;
    }
    .close-modal-btn:hover {
      color: white;
    }
    .form-group {
      margin-bottom: 16px;
    }
    .form-group label {
      display: block;
      font-size: 13px;
      font-weight: 600;
      color: var(--text-muted);
      margin-bottom: 6px;
    }
    .form-control {
      width: 100%;
      background-color: var(--bg-tertiary);
      border: 1px solid var(--border-color);
      border-radius: 8px;
      padding: 10px 14px;
      color: white;
      font-size: 14px;
      font-family: inherit;
      transition: border-color 0.2s;
    }
    .form-control:focus {
      outline: none;
      border-color: var(--accent-cyan);
    }
    .modal-footer {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 24px;
      border-top: 1px solid var(--border-color);
      padding-top: 16px;
    }
    .btn {
      padding: 10px 20px;
      border-radius: 8px;
      font-size: 14px;
      font-weight: 600;
      cursor: pointer;
      transition: all 0.2s;
      border: none;
    }
    .btn-secondary {
      background-color: var(--bg-tertiary);
      color: var(--text-main);
      border: 1px solid var(--border-color);
    }
    .btn-secondary:hover {
      background-color: rgba(255, 255, 255, 0.05);
    }
    .btn-primary {
      background: linear-gradient(135deg, var(--accent-cyan) 0%, var(--accent-purple) 100%);
      color: white;
    }
    .btn-primary:hover {
      box-shadow: 0 0 15px rgba(6, 182, 212, 0.4);
    }
    .edit-btn {
      background: transparent;
      border: none;
      color: var(--text-muted);
      cursor: pointer;
      padding: 6px;
      border-radius: 6px;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      transition: all 0.2s ease;
      margin-right: 4px;
    }
    .edit-btn:hover {
      color: var(--accent-cyan);
      background-color: rgba(6, 182, 212, 0.1);
    }
    .edit-btn i {
      width: 16px;
      height: 16px;
    }

    /* Calendar & Streak Banner Styling */
    .calendar-grid {
      display: grid;
      grid-template-columns: repeat(7, 1fr);
      gap: 6px;
      text-align: center;
      margin-top: 12px;
    }
    .calendar-day-header {
      font-size: 11px;
      font-weight: 700;
      color: var(--text-muted);
      text-transform: uppercase;
      padding: 6px 0;
    }
    .calendar-day {
      background-color: var(--bg-tertiary);
      border: 1px solid var(--border-color);
      border-radius: 8px;
      aspect-ratio: 1;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      font-size: 13px;
      font-weight: 600;
      color: var(--text-muted);
      position: relative;
      transition: all 0.2s ease;
    }
    .calendar-day.today {
      border-color: var(--accent-cyan);
      color: white;
    }
    .calendar-day.has-workout {
      background: linear-gradient(135deg, rgba(16, 185, 129, 0.15) 0%, rgba(6, 182, 212, 0.15) 100%);
      border-color: var(--accent-emerald);
      color: #34d399;
      box-shadow: 0 0 10px rgba(16, 185, 129, 0.2);
    }
    .calendar-day.has-workout::after {
      content: '🔥';
      font-size: 9px;
      position: absolute;
      bottom: 2px;
    }
    .calendar-day.empty {
      background: transparent;
      border: none;
    }
    .calendar-header-title {
      font-family: 'Outfit', sans-serif;
      font-size: 16px;
      font-weight: 700;
      color: white;
      text-align: center;
      margin-bottom: 12px;
    }

    /* Challenge Grid Styling */
    .challenge-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 20px;
      margin-bottom: 24px;
    }
    @media (max-width: 992px) {
      .challenge-grid {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <header>
    <div class="brand-section">
      <div class="brand-icon">
        <i data-lucide="dumbbell"></i>
      </div>
      <div>
        <h1>AI PT 대시보드</h1>
        <p>운동, 식단, 체중, 리포트를 한 곳에서 실시간 확인합니다.</p>
      </div>
    </div>

    <div class="nav-tabs">
